let punkty = 100;
let punktyKopia = punkty;
punktyKopia = 50;

console.log(punkty);       // 100 - niezmienione
console.log(punktyKopia);  // 50

const owoce = ["jablko", "banan"];
const owoce2 = owoce;
owoce2.push("gruszka");

console.log(owoce); // ['jablko', 'banan', 'gruszka']
// owoce ZOSTALA zmieniona, mimo ze modyfikowalismy owoce2 - obie
// zmienne wskazuja na TA SAMA tablice w pamieci (typ referencyjny)

const liczby = [1, 2, 3];
const liczby2 = [...liczby];
liczby2.push(4);

console.log(liczby); // [1, 2, 3] - NIEZMIENIONE
console.log(liczby2); // [1, 2, 3, 4]

const auto = { marka: "Toyota", silnik: { moc: 120 } };
const auto2 = { ...auto };
auto2.marka = "Honda";

console.log(auto.marka); // "Toyota" - niezmienione

const auto = { marka: "Toyota", silnik: { moc: 120 } };
const auto2 = { ...auto };
auto2.silnik.moc = 150;

console.log(auto.silnik.moc); // 150 - ZMIENIONE! mimo ze modyfikowalismy auto2
// spread to KOPIA PLYTKA (shallow) - wlasciwosc 'silnik' na najwyzszym
// poziomie zostala skopiowana, ale JEJ WARTOSC (zagniezdzony obiekt)
// to WCIAZ REFERENCJA do TEGO SAMEGO obiektu co w auto

function zmienNazwe(obiekt) {
  obiekt.nazwa = "Zmieniono";
}

const moj = { nazwa: "Stare" };
zmienNazwe(moj);
console.log(moj); // { nazwa: 'Zmieniono' } - ZMIENIONY, mimo braku return

const firma = { nazwa: "TechCorp", adres: { miasto: "Warszawa", kod: "00-001" } };
const kopia = { ...firma, adres: { ...firma.adres } };

kopia.adres.miasto = "Krakow";
console.log(firma.adres.miasto); // "Warszawa" - POPRAWNIE niezmienione
console.log(kopia.adres.miasto); // "Krakow"

function saTaSamaTablica(a, b) {
  return a === b;
}

console.log(saTaSamaTablica([1, 2, 3], [1, 2, 3])); // false - DWIE osobne tablice

const x = [1, 2, 3];
const y = x;
console.log(saTaSamaTablica(x, y)); // true - TA SAMA tablica

let temperatura = 20.5;
let kopiaTemperatury = temperatura;
kopiaTemperatury = 30.0;

console.log(temperatura);       // 20.5
console.log(kopiaTemperatury);  // 30

function dodajProdukt(koszyk, produkt) {
  koszyk.push(produkt);
}

const zakupy = ["chleb"];
dodajProdukt(zakupy, "mleko");
console.log(zakupy); // ['chleb', 'mleko'] - zmienione, mimo braku return

function zmienString(s) {
  s = s + "!";
}

let tekst = "Ala";
zmienString(tekst);
console.log(tekst); // "Ala" - NIEZMIENIONE, w odroznieniu od obiektow/tablic

const a = { x: 1 };
const b = { x: 1 };

console.log(a === b); // false - dwa OSOBNE obiekty, rozne referencje
console.log(JSON.stringify(a) === JSON.stringify(b)); // true - identyczne STRINGI
// === porownuje referencje (adresy) dla obiektow, nie zawartosc -
// zamiana na string przez JSON.stringify() pozwala porownac ZAWARTOSC,
// bo stringi (typ wartosciowy) porownywane sa przez wartosc

const oryginal = { a: 1, b: 2, c: 3 };
const kopia = { ...oryginal };
kopia.d = 4;

console.log(oryginal); // { a: 1, b: 2, c: 3 } - bez 'd'
console.log(kopia);    // { a: 1, b: 2, c: 3, d: 4 }

function resetujTablice(tablica) {
  tablica = []; // to NIE modyfikuje oryginalu - tworzy NOWA tablice TYLKO lokalnie
}

const dane = [1, 2, 3];
resetujTablice(dane);
console.log(dane); // [1, 2, 3] - BEZ ZMIAN! przypisanie do parametru nie wplywa na oryginal

function wyczyscNaprawde(tablica) {
  tablica.length = 0;
}

const dane = [1, 2, 3];
wyczyscNaprawde(dane);
console.log(dane); // [] - POPRAWNIE wyczyszczone, bo to modyfikacja zawartosci

const zamowienie = { produkty: ["A", "B"], suma: 100 };
const kopiaZamowienia = { ...zamowienie, produkty: [...zamowienie.produkty] };

kopiaZamowienia.produkty.push("C");

console.log(zamowienie.produkty);      // ['A', 'B'] - niezmienione
console.log(kopiaZamowienia.produkty); // ['A', 'B', 'C']

function test() {
  const a = [1, 2, 3];
  const b = a;
  return a === b;
}

console.log(test()); // true
// a i b przechowuja DOKLADNIE TEN SAM adres w pamieci (bez spreadu) -
// to nie sa dwie rozne tablice o tej samej zawartosci, tylko
// JEDNA tablica, do ktorej prowadza DWIE zmienne/'sciezki dostepu'

const stan = { licznik: 0 };

function zwiekszLicznik(obiektStanu) {
  obiektStanu.licznik++;
}

zwiekszLicznik(stan);
zwiekszLicznik(stan);
zwiekszLicznik(stan);

console.log(stan.licznik); // 3

let a = "tekst";
let b = a;
a = "zmienione";

console.log(b); // "tekst" - NIEZMIENIONE, string to typ wartosciowy

function polaczTablice(a, b) {
  return [...a, ...b];
}

const x = [1, 2];
const y = [3, 4];
const polaczone = polaczTablice(x, y);

console.log(polaczone); // [1, 2, 3, 4]
console.log(x, y);      // [1, 2] [3, 4] - oba niezmienione

const a = { wartosc: 10 };
const b = a;
b.wartosc = 99;

console.log(a.wartosc === b.wartosc); // true
console.log(a.wartosc); // 99
// a i b to DOKLADNIE TA SAMA referencja - modyfikacja przez b.wartosc
// to modyfikacja JEDYNEGO, wspolnego obiektu, ktory 'widza' oba a i b

const macierz = [[1, 2], [3, 4]];
const kopiaMacierzy = [...macierz];
kopiaMacierzy[0][0] = 99;

console.log(macierz[0][0]); // 99 - ZMIENIONE!
// spread skopiowal TYLKO referencje do wewnetrznych tablic ([1,2] i [3,4]),
// nie ich zawartosc - kopiaMacierzy[0] i macierz[0] to WCIAZ ta sama
// wewnetrzna tablica, dokladnie jak przy zagniezdzonych obiektach

function test(a, b) {
  return a == b;
}

console.log(test([1, 2, 3], [1, 2, 3])); // false
// w odroznieniu od prymitywow (gdzie == konwertuje typy), dla OBIEKTOW
// i TABLIC zarowno == jak i === porownuja WYLACZNIE referencje -
// dwie osobne tablice o identycznej zawartosci NIGDY nie sa sobie rowne
// przez == ani ===, niezaleznie od zawartosci

const konfiguracja = { ustawienia: { jasnosc: 50, kontrast: 30 } };
const kopiaGleboka = structuredClone(konfiguracja);

kopiaGleboka.ustawienia.jasnosc = 100;

console.log(konfiguracja.ustawienia.jasnosc); // 50 - POPRAWNIE niezmienione
console.log(kopiaGleboka.ustawienia.jasnosc);  // 100

function test() {
  const a = 5;
  const b = { wartosc: 5 };
  return typeof a === typeof b;
}

console.log(test()); // false
// typeof a to "number" (typ wartosciowy), typeof b to "object"
// (typ referencyjny) - fakt, ze OBIEKT b 'zawiera' te sama liczbe 5,
// NIE zmienia tego, ze SAM b jest typu referencyjnego, kopiowanego
// przez adres, a nie przez wartosc

const listaZadan = { zadania: ["A", "B", "C"] };

function usunOstatnie(obiekt) {
  obiekt.zadania.pop();
}

usunOstatnie(listaZadan);
console.log(listaZadan.zadania); // ['A', 'B']

const a = true;
const b = a;
console.log(a === b); // true - ale to NIE jest 'ta sama referencja',
// to DWIE NIEZALEZNE kopie o identycznej wartosci true
// boolean, jak kazdy typ wartosciowy (string, number, bigint, symbol,
// null, undefined), zawsze kopiuje SAMA WARTOSC przy przypisaniu -
// nigdy adres/referencje, w przeciwienstwie do obiektow i tablic

function porownajGleboko(a, b) {
  return JSON.stringify(a) === JSON.stringify(b);
}

console.log(porownajGleboko({ x: 1, y: 2 }, { x: 1, y: 2 })); // true

const bazowy = { typ: "produkt", cena: 100 };
const produkt1 = { ...bazowy, nazwa: "Laptop" };
const produkt2 = { ...bazowy, nazwa: "Telefon" };

produkt1.cena = 150;

console.log(produkt1.cena); // 150
console.log(produkt2.cena); // 100 - niezmienione
console.log(bazowy.cena);   // 100 - niezmienione

function test() {
  const a = [1, 2, 3];
  const b = a.slice();
  b.push(4);
  return [a, b];
}

console.log(test()); // [[1, 2, 3], [1, 2, 3, 4]]

